-- Read-only analytics for the administrative panel. No historical DML.
CREATE OR REPLACE FUNCTION private.panel_v2_authorized_session(p_secret text, p_session_hash text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT private.panel_v2_broker_ok(p_secret)
   AND coalesce(p_session_hash,'') ~ '^[0-9a-f]{64}$'
   AND EXISTS (SELECT 1 FROM private.panel_v2_sessions s WHERE s.token_hash=p_session_hash AND s.expires_at>now())
$$;
REVOKE ALL ON FUNCTION private.panel_v2_authorized_session(text,text) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.panel_v2_get_dashboard(p_broker_secret text,p_session_hash text,p_filters jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE f jsonb:=coalesce(p_filters,'{}'::jsonb); bad text[]; a timestamptz; z timestamptz;
BEGIN
 IF NOT private.panel_v2_authorized_session(p_broker_secret,p_session_hash) THEN RAISE EXCEPTION 'unauthorized'; END IF;
 IF jsonb_typeof(f)<>'object' THEN RAISE EXCEPTION 'invalid_filters'; END IF;
 SELECT array_agg(key) INTO bad FROM jsonb_object_keys(f) key WHERE key NOT IN ('start_at','end_at','experience','catalog_key','source','campaign','term','content','event','device','lot','search');
 IF bad IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_each_text(f) WHERE length(value)>200) THEN RAISE EXCEPTION 'invalid_filters'; END IF;
 BEGIN a:=nullif(f->>'start_at','')::timestamptz; z:=nullif(f->>'end_at','')::timestamptz; EXCEPTION WHEN others THEN RAISE EXCEPTION 'invalid_filters'; END;
 IF a IS NOT NULL AND z IS NOT NULL AND z<=a THEN RAISE EXCEPTION 'invalid_filters'; END IF;
 RETURN (WITH x AS (
 SELECT e.*,coalesce(nullif(e.session_id,''),e.id::text) sid,coalesce(e.catalog_key,case when e.catalog_name='Quarto de Milha - Martendal Weekend 2026' then 'machos' end) ck
 FROM public.martendal_tracking_events e WHERE (a IS NULL OR e.created_at>=a) AND (z IS NULL OR e.created_at<z)
 AND (coalesce(f->>'experience','')='' OR e.experience_type=f->>'experience')
 AND (coalesce(f->>'catalog_key','')='' OR coalesce(e.catalog_key,case when e.catalog_name='Quarto de Milha - Martendal Weekend 2026' then 'machos' end)=f->>'catalog_key')
 AND (coalesce(f->>'source','')='' OR coalesce(nullif(e.traffic_source,''),'Direto / Desconhecido')=f->>'source')
 AND (coalesce(f->>'campaign','')='' OR coalesce(nullif(e.utm_campaign,''),'Sem campanha identificada')=f->>'campaign')
 AND (coalesce(f->>'term','')='' OR coalesce(nullif(e.utm_term,''),'Sem conjunto identificado')=f->>'term')
 AND (coalesce(f->>'content','')='' OR coalesce(nullif(e.utm_content,''),'Sem criativo identificado')=f->>'content')
 AND (coalesce(f->>'event','')='' OR e.event_type=f->>'event') AND (coalesce(f->>'device','')='' OR coalesce(nullif(e.device_type,''),'Unknown')=f->>'device')
 AND (coalesce(f->>'lot','')='' OR coalesce(e.catalog_key,case when e.catalog_name='Quarto de Milha - Martendal Weekend 2026' then 'machos' end,'')||':'||coalesce(e.lot_number,'')=f->>'lot')
 AND (coalesce(f->>'search','')='' OR concat_ws(' ',e.lot_number,e.horse_name) ILIKE '%'||(f->>'search')||'%')
), sm AS (SELECT count(*) filter(where event_type in('page_view','catalog_view')) accesses,count(distinct sid) filter(where event_type in('page_view','catalog_view')) uniques,count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) clicks,count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) click_sessions,count(*) filter(where experience_type='squeeze' and event_type='page_view') sq_accesses,count(distinct sid) filter(where experience_type='squeeze' and event_type='page_view') sq_uniques,count(*) filter(where experience_type='squeeze' and event_type='whatsapp_click') sq_clicks,count(distinct sid) filter(where experience_type='squeeze' and event_type='whatsapp_click') sq_click_sessions,count(*) filter(where experience_type='catalog' and event_type='catalog_view') cat_accesses,count(distinct sid) filter(where experience_type='catalog' and event_type='catalog_view') cat_uniques,count(*) filter(where experience_type='catalog' and event_type='lot_view') lot_views,count(distinct sid) filter(where experience_type='catalog' and event_type='lot_view') lot_sessions,count(distinct (sid,ck,lot_number)) filter(where experience_type='catalog' and event_type='lot_view' and lot_number is not null) unique_lot_views,count(*) filter(where experience_type='catalog' and event_type='catalog_video_click') video_clicks,count(distinct sid) filter(where experience_type='catalog' and event_type='catalog_video_click') video_sessions,count(*) filter(where experience_type='catalog' and event_type in('catalog_whatsapp_click','lot_whatsapp_click')) cat_wa_clicks,count(distinct sid) filter(where experience_type='catalog' and event_type in('catalog_whatsapp_click','lot_whatsapp_click')) cat_wa_sessions,count(*) filter(where experience_type='catalog' and event_type='lot_whatsapp_click') interest_clicks,count(distinct sid) filter(where experience_type='catalog' and event_type='lot_whatsapp_click') interested_sessions,count(distinct (sid,ck,lot_number)) filter(where experience_type='catalog' and event_type='lot_whatsapp_click' and lot_number is not null) interested_lots,count(*) filter(where experience_type='catalog' and event_type='pdf_download') pdfs FROM x), ts AS (SELECT to_char(created_at at time zone 'America/Porto_Velho','DD/MM') label,min(created_at) ord,count(*) filter(where event_type in('page_view','catalog_view')) accesses,count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) clicks FROM x GROUP BY 1), grp AS (SELECT 'source' kind,coalesce(nullif(traffic_source,''),'Direto / Desconhecido') k,count(*) filter(where event_type in('page_view','catalog_view')) views,count(distinct sid) filter(where event_type in('page_view','catalog_view')) uniques,count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) clicks,count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) click_sessions FROM x GROUP BY 1,2 UNION ALL SELECT 'utm_source',coalesce(nullif(utm_source,''),'sem utm_source'),count(*) filter(where event_type in('page_view','catalog_view')),count(distinct sid) filter(where event_type in('page_view','catalog_view')),count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')),count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) FROM x GROUP BY 1,2 UNION ALL SELECT 'campaign',coalesce(nullif(utm_campaign,''),'Sem campanha identificada'),count(*) filter(where event_type in('page_view','catalog_view')),count(distinct sid) filter(where event_type in('page_view','catalog_view')),count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')),count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) FROM x GROUP BY 1,2 UNION ALL SELECT 'term',coalesce(nullif(utm_term,''),'Sem conjunto identificado'),count(*) filter(where event_type in('page_view','catalog_view')),count(distinct sid) filter(where event_type in('page_view','catalog_view')),count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')),count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) FROM x GROUP BY 1,2 UNION ALL SELECT 'content',coalesce(nullif(utm_content,''),'Sem criativo identificado'),count(*) filter(where event_type in('page_view','catalog_view')),count(distinct sid) filter(where event_type in('page_view','catalog_view')),count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')),count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) FROM x GROUP BY 1,2 UNION ALL SELECT 'device',coalesce(nullif(device_type,''),'Unknown'),count(*) filter(where event_type in('page_view','catalog_view')),count(distinct sid) filter(where event_type in('page_view','catalog_view')),count(*) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')),count(distinct sid) filter(where event_type in('whatsapp_click','catalog_whatsapp_click','lot_whatsapp_click')) FROM x GROUP BY 1,2), lg AS (SELECT ck,lot_number,max(horse_name) horse,max(video_url) video_url,count(distinct sid) filter(where event_type='lot_view') unique_views,count(*) filter(where event_type='lot_view') total_views,count(*) filter(where event_type='catalog_video_click') video_clicks,count(distinct sid) filter(where event_type='catalog_video_click') video_sessions,count(*) filter(where event_type='lot_whatsapp_click') wa_clicks,count(distinct sid) filter(where event_type='lot_whatsapp_click') interested FROM x WHERE experience_type='catalog' and lot_number is not null GROUP BY 1,2)
SELECT jsonb_build_object('summary',to_jsonb(sm),'timeseries',coalesce((select jsonb_agg(jsonb_build_object('day',label,'acessos',accesses,'cliques',clicks) order by ord) from ts),'[]'::jsonb),'breakdowns',coalesce((select jsonb_object_agg(kind,rows) from (select kind,jsonb_agg(jsonb_build_object('key',k,'views',views,'uniques',uniques,'clicks',clicks,'clickSessions',click_sessions,'rate',case when uniques=0 then 0 else round(100.0*click_sessions/uniques,1) end) order by clicks desc,views desc) rows from grp group by kind) g),'{}'::jsonb),'lots',coalesce((select jsonb_agg(jsonb_build_object('key',coalesce(ck,'machos')||':'||lot_number,'catalogKey',coalesce(ck,'machos'),'lot',lot_number,'horse',horse,'videoUrl',video_url,'uniqueViews',unique_views,'totalViews',total_views,'videoClicks',video_clicks,'videoSessions',video_sessions,'waClicks',wa_clicks,'interested',interested,'rate',case when unique_views=0 then 0 else round(100.0*interested/unique_views,1) end) order by unique_views desc) from lg),'[]'::jsonb),'filter_options',jsonb_build_object('sources',coalesce((select jsonb_agg(distinct coalesce(nullif(traffic_source,''),'Direto / Desconhecido')) from x),'[]'::jsonb),'campaigns',coalesce((select jsonb_agg(distinct coalesce(nullif(utm_campaign,''),'Sem campanha identificada')) from x),'[]'::jsonb),'terms',coalesce((select jsonb_agg(distinct coalesce(nullif(utm_term,''),'Sem conjunto identificado')) from x),'[]'::jsonb),'contents',coalesce((select jsonb_agg(distinct coalesce(nullif(utm_content,''),'Sem criativo identificado')) from x),'[]'::jsonb),'devices',coalesce((select jsonb_agg(distinct coalesce(nullif(device_type,''),'Unknown')) from x),'[]'::jsonb),'lots',coalesce((select jsonb_agg(distinct coalesce(ck,'machos')||':'||lot_number) filter(where lot_number is not null) from x),'[]'::jsonb))) FROM sm); END $$;
REVOKE ALL ON FUNCTION public.panel_v2_get_dashboard(text,text,jsonb) FROM PUBLIC,authenticated;
GRANT EXECUTE ON FUNCTION public.panel_v2_get_dashboard(text,text,jsonb) TO anon,service_role;

CREATE OR REPLACE FUNCTION public.panel_v2_get_tracking_events_page(p_broker_secret text,p_session_hash text,p_cursor_at timestamptz DEFAULT NULL,p_cursor_id uuid DEFAULT NULL,p_page_size integer DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r jsonb; BEGIN
 IF NOT private.panel_v2_authorized_session(p_broker_secret,p_session_hash) THEN RAISE EXCEPTION 'unauthorized'; END IF;
 IF p_page_size NOT BETWEEN 1 AND 100 OR (p_cursor_at IS NULL)<>(p_cursor_id IS NULL) THEN RAISE EXCEPTION 'invalid_page'; END IF;
 WITH q AS (SELECT * FROM public.martendal_tracking_events WHERE p_cursor_at IS NULL OR (created_at,id)<(p_cursor_at,p_cursor_id) ORDER BY created_at DESC,id DESC LIMIT p_page_size+1), p AS (SELECT * FROM q LIMIT p_page_size) SELECT jsonb_build_object('events',coalesce(jsonb_agg(to_jsonb(p) order by created_at desc,id desc),'[]'::jsonb),'hasMore',(select count(*)>p_page_size from q),'nextCursor',(select jsonb_build_object('created_at',created_at,'id',id) from p order by created_at asc,id asc limit 1)) INTO r FROM p; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.panel_v2_get_tracking_events_page(text,text,timestamptz,uuid,integer) FROM PUBLIC,authenticated;
GRANT EXECUTE ON FUNCTION public.panel_v2_get_tracking_events_page(text,text,timestamptz,uuid,integer) TO anon,service_role;
